package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_Integer() {
        Number res = NumberUtils.createNumber("123");
        assertTrue(res instanceof Integer);
        assertEquals(123, ((Integer) res).intValue());
    }

    @Test
    public void testCreateNumber_Long() {
        Number res = NumberUtils.createNumber("1234567890123");
        assertTrue(res instanceof Long);
        assertEquals(1234567890123L, ((Long) res).longValue());
    }

    @Test
    public void testCreateNumber_BigInteger() {
        String bigStr = "123456789012345678901234567890";
        Number res = NumberUtils.createNumber(bigStr);
        assertTrue(res instanceof BigInteger);
        assertEquals(new BigInteger(bigStr), (BigInteger) res);
    }

    @Test
    public void testCreateNumber_Float() {
        // numDecimals <= 7
        Number res = NumberUtils.createNumber("1.2345");
        assertTrue(res instanceof Float);
        assertEquals(1.2345f, ((Float) res).floatValue(), 0.00001f);
    }

    @Test
    public void testCreateNumber_Double() {
        // numDecimals between 8 and 16
        Number res = NumberUtils.createNumber("1.123456789");
        assertTrue(res instanceof Double);
        assertEquals(1.123456789, ((Double) res).doubleValue(), 0.000000001);
    }

    @Test
    public void testCreateNumber_BigDecimal() {
        // numDecimals > 16
        String longDec = "1.1234567890123456789";
        Number res = NumberUtils.createNumber(longDec);
        assertTrue(res instanceof BigDecimal);
        assertEquals(new BigDecimal(longDec), (BigDecimal) res);
    }

    @Test
    public void testCreateNumber_WithExponent() {
        // Exponential notation usually results in Double or Float
        Number res = NumberUtils.createNumber("1.2e3");
        assertTrue(res instanceof Double || res instanceof Float);
        assertEquals(1200.0, ((Number) res).doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_SuffixL() {
        // Test Long suffix
        Number res = NumberUtils.createNumber("123L");
        assertTrue(res instanceof Long);
        assertEquals(123L, ((Long) res).longValue());

        // Test BigInteger via L suffix (too large for Long)
        String huge = "9223372036854775808L"; // Long.MAX_VALUE + 1
        Number resBig = NumberUtils.createNumber(huge);
        assertTrue(resBig instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_SuffixF() {
        Number res = NumberUtils.createNumber("123.45f");
        assertTrue(res instanceof Float);
        assertEquals(123.45f, ((Float) res).floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_SuffixD() {
        Number res = NumberUtils.createNumber("123.45d");
        assertTrue(res instanceof Double);
        assertEquals(123.45, ((Double) res).doubleValue(), 0.001);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidSuffix() {
        NumberUtils.createNumber("123x");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidFormat() {
        NumberUtils.createNumber("1.2.3");
    }

    @Test
    public void testCreateNumber_AllZeros() {
        // Test the allZeros logic for Float/Double precision fallback
        // If value is 0.0 but string has non-zeros, it should fallback to BigDecimal
        Number res = NumberUtils.createNumber("0.0000000000000000000000000000001");
        assertTrue(res instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_ExponentEdgeCases() {
        // Test invalid exponent positions
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("1.2e"));
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("1.2e-"));
    }

    @Test
    public void testCreateNumber_Negative() {
        Number res = NumberUtils.createNumber("-123");
        assertTrue(res instanceof Integer);
        assertEquals(-123, ((Integer) res).intValue());
    }

    @Test
    public void testCreateNumber_DecimalOnly() {
        Number res = NumberUtils.createNumber("123.");
        // Depending on implementation, 123. might be treated as float or double
        assertNotNull(res);
    }

    @Test
    public void testCreateNumber_ComplexExponentWithSuffix() {
        // Test case: 1.2e3L (though unlikely, checking logic flow)
        // The code checks suffix 'L' and if dec/exp are null.
        // If 'e' is present, exp is not null, so it goes to default/throws.
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("1.2e3L"));
    }

    // Helper to handle JUnit 4 expected exception in lambda style if needed
    private void assertThrows(Class<? extends Throwable> expected, Runnable runnable) {
        try {
            runnable.run();
            fail("Expected exception " + expected.getName());
        } catch (Throwable t) {
            if (!expected.isInstance(t)) {
                fail("Expected " + expected.getName() + " but got " + t.getClass().getName());
            }
        }
    }
}
